/*
 * A297268  Numbers whose base-9 digits have equal down-variation and
 *          up-variation; see Comments.
 * https://oeis.org/A297268
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = nth positive integer whose base‑9 first and last digits
 *            are equal
 * Range:     u8 n <= 36, u16 n <= 7289, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   first_equals_last
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by scanning successive integers and keeping only
   those for which the most significant and least significant base‑9 digits
   coincide.  The result for any n ≥ 1 is found in O(n) time with single
   global cache.  This implementation works for all provided seq_t/idx_t
   types and for both C and C++ builds. */

#include <stdlib.h>
#include "../utils/first_equals_last.h"

/* Global cache of computed sequence values. */
static seq_t *cache = NULL;          /* array of a(i) */
static idx_t cache_size = 0;         /* number of elements stored */
static idx_t cache_cap = 0;          /* current allocation capacity */
static idx_t next_candidate = 1;     /* next integer to test */

/* Expand cache capacity to at least 'need' elements.  Capacity grows
   geometrically to keep amortised time small. */
static void grow_cache(idx_t need)
{
    if (need <= cache_cap) return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    while (new_cap < (size_t)need) new_cap *= 2;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) exit(EXIT_FAILURE);  /* allocation failed */
    cache = tmp;
    cache_cap = new_cap;
}

/* Public sequence function.  Computes a(n) for any n ≥ 1.  Results are
   memoised in the static cache, so rapid repeated calls are O(1). */
seq_t a(idx_t n)
{
    if (n < 1) return 0;          /* undefined for n=0, but safe guard */

    /* Grow cache until it contains at least n elements. */
    if (n > cache_size) {
        grow_cache(n);
        while (cache_size < n) {
            if (first_equals_last(next_candidate)) {
                cache[cache_size++] = (seq_t)next_candidate;
            }
            next_candidate++;
        }
    }

    return cache[n - 1];
}
